{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 6,
      "text_ar": "ثم تأملت هذه الأشياء، وجميعها صنعت بي وحدي لا بغيري؛ كما بي أيضاً ستنقضي لا بغيري.",
      "verse": 6
    },
    {
      "chapter": 6,
      "text_ar": "فأجبت وقلت: ما هو انقسام الأزمنة؟ ومتى تكون نهاية الأول وبداية الدهر الآتي؟",
      "verse": 7
    },
    {
      "chapter": 6,
      "text_ar": "فقال لي: من إبراهيم إلى إسحاق، لأنه ولد له يعقوب وعيسو، لأن يد يعقوب أمسكت بعقب عيسو منذ البداية.",
      "verse": 8
    },
    {
      "chapter": 6,
      "text_ar": "لأن عيسو هو نهاية هذا الدهر، ويعقوب هو بداية الدهر الآتي.",
      "verse": 9
    },
    {
      "chapter": 6,
      "text_ar": "بداية الإنسان هي يده، ونهاية الإنسان هي عقبه. لا تطلب شيئاً آخر بين العقب واليد يا عزرا!",
      "verse": 10
    }
  ]
}
